export function findLocalSyllabus(search) {
  if (!search) return null;
  const q = String(search).toLowerCase().replace(/[^a-z0-9]+/g, ' ');
  let best = null; let bestScore = 0;
  for (const s of LOCAL_SYLLABUS) {
    const name = (s.file || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ');
    const tokens = q.split(' ').filter(t => t.length > 2);
    let score = 0;
    for (const t of tokens) { if (name.includes(t)) score += 1; }
    if (score > bestScore) { bestScore = score; best = s; }
  }
  return bestScore > 0 ? best : null;
}
